pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Set up the contract: the fuzzer picks a MinSum value and initializes the contract.
        c.SetMinSum(minSum);
        c.Initialized();
        // Ensure deposit amount is at least MinSum so that Collect can be meaningful.
        vm.assume(depositAmount >= minSum);
        // The actor deposits funds.
        address actor = address(0x1234);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();
        // The actor attempts to collect some amount. We need collectAmount to be within its balance.
        vm.assume(collectAmount <= depositAmount);
        vm.prank(actor);
        // Drive the Collect entry point.
        c.Collect(collectAmount);
        // After Collect, the state variable MinSum must equal the value that was set.
        assertTrue(c.MinSum() == minSum);
    }
}

