pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 minSumVal) public {
        // Restrict domain to avoid overflows and ensure meaningful values.
        vm.assume(minSumVal > 0 && minSumVal < type(uint256).max / 2);
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(collectAmount > 0 && collectAmount < type(uint256).max / 2);
        vm.assume(depositAmount >= minSumVal);
        vm.assume(collectAmount <= depositAmount);

        // Deploy an adversarial helper that always reverts on receiving Ether.
        Reverter reverter = new Reverter();
        c.SetLogFile(address(reverter));

        // Initialize: set MinSum and mark as initialized.
        c.SetMinSum(minSumVal);
        c.Initialized();

        // Deposit funds for the test contract itself.
        vm.deal(address(this), depositAmount);
        c.Deposit{value: depositAmount}();

        // Record MinSum before the Collect call.
        uint256 minSumBefore = c.MinSum();

        // Attempt to collect; since LogFile is the reverter, the low-level call in Collect
        // will revert, making the entire Collect transaction revert.
        vm.prank(address(this));
        try c.Collect(collectAmount) {
            // If Collect does not revert (should not happen with reverter LogFile),
            // we check the invariant.
        } catch {
            // Collect reverted; MinSum must remain unchanged.
        }

        uint256 minSumAfter = c.MinSum();
        // General invariant: MinSum never changes after initialization,
        // regardless of whether Collect reverts or not.
        assertTrue(minSumBefore == minSumAfter);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter: always reverts");
    }
}

