pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 collectAmt) public {
        // 1. Restrict to admissible domain: minSum > 0 so it differs from the bug's zero default,
        // and collectAmt <= minSum so Collect can succeed if balances are sufficient.
        vm.assume(minSum > 0);
        vm.assume(collectAmt > 0 && collectAmt <= minSum);

        // Deploy an adversarial callee that always reverts on receiving ETH.
        // This ensures Collect does not complete a transfer but still subtracts balances.
        // In the reference, MinSum remains invariant; in the buggy, MinSum stays zero.
        Reverter reverter = new Reverter();

        // 2. Initialize the contract: set MinSum, set LogFile, mark initialized.
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Fund the reverter address and deposit into C via the reverter to give it balances.
        vm.deal(address(reverter), 1 ether);
        vm.prank(address(reverter));
        c.Deposit{value: minSum}();

        // Now attempt to collect from the reverter's balance.
        // The reverter's receive/fallback will revert the ETH transfer, but the subtraction happens first.
        // This is a non-reverting call to Collect from the perspective of C (no revert bubbles from the call
        // because Solidity 0.8 low-level call returns false, not revert). We catch the success boolean.
        vm.prank(address(reverter));
        bool ok = false;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }
        // The call itself should not revert; the transfer fails but the subtraction succeeded.
        assertTrue(ok);

        // 3. Assert the property: MinSum must equal the initially set value (minSum).
        // The buggy version leaves MinSum == 0, so this assertion fails when minSum != 0.
        assertTrue(c.MinSum() == minSum);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
    receive() external payable {
        revert();
    }
}

