contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint _val) public {
        bool revertedBefore = false;
        bool revertedAfter = false;

        (bool succ1, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _val));
        revertedBefore = !succ1;

        c.Initialized();

        (bool succ2, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _val));
        revertedAfter = !succ2;

        assert(revertedBefore && !revertedAfter);
    }
}

